public class Account {
    public final String id;
    public final String tier;
    public final String currency;
    public BigDecimal balance;

    public Account(String id, String tier, String currency, BigDecimal balance) {
        this.id = id;
        this.tier = tier;
        this.currency = currency;
        this.balance = balance;
    }
}

package com.rustyledger;

import java.math.BigDecimal;

public class Transaction {
    public final String id;
    public final String verb;
    public final String date;
    public final String fromId;
    public final String toId;
    public final BigDecimal amount;
    public final String currency;
    public final BigDecimal fee;
    public final BigDecimal credited;
    public boolean reversed;

    public Transaction(String id, String verb, String date, String fromId, String toId, 
                       BigDecimal amount, String currency, BigDecimal fee, BigDecimal credited) {
        this.id = id;
        this.verb = verb;
        this.date = date;
        this.fromId = fromId;
        this.toId = toId;
        this.amount = amount;
        this.currency = currency;
        this.fee = fee;
        this.credited = credited;
        this.reversed = false;
    }
}

package com.rustyledger;

import java.math.BigDecimal;
import java.util.HashMap;
import java.util.Map;

public class AccountManager {
    private final Map<String, Account> accounts = new HashMap<>();
    private final Map<String, BigDecimal> used = new HashMap<>();

    public void openAccount(String id, String tier, String currency, BigDecimal balance) {
        accounts.put(id, new Account(id, tier, currency, balance));
    }

    public Account getAccount(String id) {
        return accounts.get(id);
    }

    public boolean exists(String id) {
        return accounts.containsKey(id);
    }

    public BigDecimal getUsedToday(String id, String date) {
        BigDecimal u = used.get(id + "|" + date);
        return u == null ? new BigDecimal("0.00") : u;
    }

    public void addUsedToday(String id, String date, BigDecimal amount) {
        used.put(id + "|" + date, getUsedToday(id, date).add(amount));
    }
}

package com.rustyledger;

import java.util.ArrayList;
import java.util.List;

public class AuditLogger {
    private final List<String> audit = new ArrayList<>();
    private int auditSeq = 0;

    public void record(String verb, String date, String outcome) {
        auditSeq++;
        audit.add(String.format("%03d  %s %s %s", auditSeq, verb, date, outcome));
    }

    public List<String> getLog() {
        return new ArrayList<>(audit);
    }
}

package com.rustyledger;

import java.math.BigDecimal;
import java.util.HashMap;
import java.util.Map;
import java.util.TreeMap;

public class ReportManager {
    private final Map<String, int[]> counts = new HashMap<>();
    private final Map<String, Map<String, BigDecimal>> fees = new HashMap<>();

    public void count(String date, int slot) {
        int[] c = counts.computeIfAbsent(date, k -> new int[2]);
        c[slot]++;
    }

    public void addFee(String date, String currency, BigDecimal delta) {
        if (delta.signum() == 0) return;
        Map<String, BigDecimal> m = fees.computeIfAbsent(date, k -> new TreeMap<>());
        BigDecimal old = m.get(currency);
        m.put(currency, old == null ? delta : old.add(delta));
    }

    public String generateReport(String date) {
        int[] c = counts.get(date);
        int ok = c == null ? 0 : c[0];
        int rejected = c == null ? 0 : c[1];
        Map<String, BigDecimal> f = fees.get(date);
        String feeText = "none";
        if (f != null && !f.isEmpty()) {
            StringBuilder sb = new StringBuilder();
            for (Map.Entry<String, BigDecimal> e : f.entrySet()) {
                if (sb.length() > 0) sb.append(", ");
                sb.append(e.getValue()).append(" ").append(e.getKey());
            }
            feeText = sb.toString();
        }
        return "REPORT " + date + "\nok: " + ok + "\nrejected: " + rejected + "\nfees: " + feeText;
    }
}

package com.rustyledger;

import java.math.BigDecimal;
import java.math.RoundingMode;

public class CurrencyConverter {
    private BigDecimal rate(String currency) {
        if (currency.equals("EUR")) return new BigDecimal("4.30");
        if (currency.equals("USD")) return new BigDecimal("4.00");
        return new BigDecimal("1.00");
    }

    public BigDecimal convert(BigDecimal amount, String from, String to, String tier) {
        BigDecimal inPln = amount.multiply(rate(from)).setScale(4, RoundingMode.HALF_UP);
        BigDecimal result = inPln.divide(rate(to), 4, RoundingMode.HALF_UP);
        if (!tier.equals("STAFF")) {
            result = result.multiply(new BigDecimal("0.985"));
        }
        return result.setScale(2, RoundingMode.HALF_DOWN);
    }
}

package com.rustyledger;

import java.math.BigDecimal;
import java.math.RoundingMode;

public class FeeCalculator {
    public BigDecimal calculateTransferFee(String tier, BigDecimal amount) {
        if (tier.equals("STANDARD")) {
            BigDecimal fee = amount.multiply(new BigDecimal("0.005")).setScale(2, RoundingMode.HALF_UP);
            return fee.max(new BigDecimal("0.20"));
        } else if (tier.equals("PREMIUM")) {
            BigDecimal fee = amount.multiply(new BigDecimal("0.0025")).setScale(2, RoundingMode.HALF_UP);
            return fee.max(new BigDecimal("0.10")).min(new BigDecimal("5.00"));
        }
        return new BigDecimal("0.00");
    }

    public BigDecimal calculateWithdrawFee(String tier) {
        return tier.equals("STANDARD") ? new BigDecimal("1.00") : new BigDecimal("0.00");
    }
}

package com.rustyledger;

import java.math.BigDecimal;

public class InstructionParser {
    public record ParseResult(boolean rejected, String rejection, String verb, String date, String[] fields, BigDecimal amount) {}

    public ParseResult parse(String line) {
        if (line == null || line.trim().isEmpty()) {
            return new ParseResult(true, "REJECTED BAD_INSTRUCTION: empty instruction", "???", null, null, null);
        }
        String[] f = line.split("\\|", -1);
        String verb = f[0];
        int want = switch (verb) {
            case "TRANSFER" -> 6;
            case "WITHDRAW", "DEPOSIT" -> 4;
            case "REVERSE" -> 3;
            default -> -1;
        };
        if (want == -1) return new ParseResult(true, "REJECTED BAD_INSTRUCTION: unknown verb " + verb, verb, null, null, null);
        if (f.length != want) return new ParseResult(true, "REJECTED BAD_INSTRUCTION: " + verb + " needs " + want + " fields", verb, null, null, null);

        String date = f[1];
        if (!date.matches("\\d{4}-\\d{2}-\\d{2}")) return new ParseResult(true, "REJECTED BAD_DATE: " + date, verb, null, null, null);

        if (verb.equals("REVERSE")) return new ParseResult(false, null, verb, date, f, null);

        String amountText = verb.equals("TRANSFER") ? f[4] : f[3];
        if (!amountText.matches("\\d+(\\.\\d{1,2})?")) return new ParseResult(true, "REJECTED BAD_AMOUNT: " + amountText, verb, date, null, null);
        BigDecimal amount = new BigDecimal(amountText).setScale(2);
        if (amount.signum() <= 0) return new ParseResult(true, "REJECTED BAD_AMOUNT: " + amountText, verb, date, null, null);

        return new ParseResult(false, null, verb, date, f, amount);
    }
}

package com.rustyledger;

import java.math.BigDecimal;
import java.util.*;

public class LedgerImpl implements Ledger {
    private final AccountManager accountManager = new AccountManager();
    private final AuditLogger auditLogger = new AuditLogger();
    private final ReportManager reportManager = new ReportManager();
    private final CurrencyConverter currencyConverter = new CurrencyConverter();
    private final FeeCalculator feeCalculator = new FeeCalculator();
    private final InstructionParser parser = new InstructionParser();
    private final Map<String, Transaction> txs = new LinkedHashMap<>();
    private int txSeq = 0;

    public void openAccount(String id, String tier, String currency, String openingBalance) {
        if (id == null || id.trim().isEmpty() || id.contains("|")) throw new IllegalArgumentException("INVALID ACCOUNT ID");
        if (!Set.of("STANDARD", "PREMIUM", "STAFF").contains(tier)) throw new IllegalArgumentException("INVALID TIER: " + tier);
        if (!Set.of("PLN", "EUR", "USD").contains(currency)) throw new IllegalArgumentException("INVALID CURRENCY: " + currency);
        if (openingBalance == null || !openingBalance.matches("\\d+(\\.\\d{1,2})?")) throw new IllegalArgumentException("INVALID AMOUNT: " + openingBalance);
        if (accountManager.exists(id)) throw new IllegalStateException("ACCOUNT EXISTS: " + id);
        accountManager.openAccount(id, tier, currency, new BigDecimal(openingBalance).setScale(2));
    }

    public String balance(String id) {
        Account a = accountManager.getAccount(id);
        if (a == null) throw new IllegalArgumentException("UNKNOWN ACCOUNT: " + id);
        return a.balance + " " + a.currency;
    }

    public List<String> auditLog() { return auditLogger.getLog(); }
    public String dailyReport(String date) { return reportManager.generateReport(date); }

    public String submit(String line) {
        InstructionParser.ParseResult res = parser.parse(line);
        if (res.rejected()) {
            String verb = res.verb(); String date = res.date();
            reportManager.count(date, 1);
            auditLogger.record(verb, date == null ? "????-??-??" : date, "REJECTED " + res.rejection().split(": ")[0].replace("REJECTED ", ""));
            return res.rejection();
        }
        return switch (res.verb()) {
            case "TRANSFER" -> doTransfer(res.date(), res.fields(), res.amount());
            case "WITHDRAW" -> doWithdraw(res.date(), res.fields(), res.amount());
            case "DEPOSIT" -> doDeposit(res.date(), res.fields(), res.amount());
            case "REVERSE" -> doReverse(res.date(), res.fields());
            default -> "REJECTED BAD_INSTRUCTION: unknown verb";
        };
    }

    private String doTransfer(String date, String[] f, BigDecimal amount) {
        Account from = accountManager.getAccount(f[2]);
        if (from == null) return reject("TRANSFER", date, "UNKNOWN_ACCOUNT", f[2]);
        Account to = accountManager.getAccount(f[3]);
        if (to == null) return reject("TRANSFER", date, "UNKNOWN_ACCOUNT", f[3]);
        if (f[2].equals(f[3])) return reject("TRANSFER", date, "SAME_ACCOUNT", "cannot transfer to the same account");
        if (!from.currency.equals(f[5])) return reject("TRANSFER", date, "CURRENCY_MISMATCH", from.id + " holds " + from.currency);

        BigDecimal fee = feeCalculator.calculateTransferFee(from.tier, amount);
        String rej = checkLimitAndFunds(date, from, amount, fee);
        if (rej != null) return reject("TRANSFER", date, rej.split(": ")[0], rej.split(": ")[1]);

        BigDecimal credited = currencyConverter.convert(amount, from.currency, to.currency, from.tier);
        from.balance = from.balance.subtract(amount.add(fee));
        to.balance = to.balance.add(credited);
        accountManager.addUsedToday(from.id, date, amount);

        String txId = nextTxId();
        txs.put(txId, new Transaction(txId, "TRANSFER", date, from.id, to.id, amount, from.currency, fee, credited));
        reportManager.addFee(date, from.currency, fee);
        return accept("TRANSFER", date, txId, "fee=" + fee + " " + from.currency);
    }

    private String doWithdraw(String date, String[] f, BigDecimal amount) {
        Account a = accountManager.getAccount(f[2]);
        if (a == null) return reject("WITHDRAW", date, "UNKNOWN_ACCOUNT", f[2]);
        BigDecimal fee = feeCalculator.calculateWithdrawFee(a.tier);
        String rej = checkLimitAndFunds(date, a, amount, fee);
        if (rej != null) return reject("WITHDRAW", date, rej.split(": ")[0], rej.split(": ")[1]);

        a.balance = a.balance.subtract(amount.add(fee));
        accountManager.addUsedToday(a.id, date, amount);
        String txId = nextTxId();
        txs.put(txId, new Transaction(txId, "WITHDRAW", date, a.id, "", amount, a.currency, fee, amount));
        reportManager.addFee(date, a.currency, fee);
        return accept("WITHDRAW", date, txId, "fee=" + fee + " " + a.currency);
    }

    private String doDeposit(String date, String[] f, BigDecimal amount) {
        Account a = accountManager.getAccount(f[2]);
        if (a == null) return reject("DEPOSIT", date, "UNKNOWN_ACCOUNT", f[2]);
        a.balance = a.balance.add(amount);
        String txId = nextTxId();
        txs.put(txId, new Transaction(txId, "DEPOSIT", date, a.id, "", amount, a.currency, new BigDecimal("0.00"), amount));
        return accept("DEPOSIT", date, txId, "fee=0.00 " + a.currency);
    }

    private String doReverse(String date, String[] f) {
        Transaction tx = txs.get(f[2]);
        if (tx == null) return reject("REVERSE", date, "UNKNOWN_TX", f[2]);
        if (!tx.verb.equals("TRANSFER")) return reject("REVERSE", date, "NOT_REVERSIBLE", tx.id + " is a " + tx.verb);
        if (tx.reversed) return reject("REVERSE", date, "ALREADY_REVERSED", tx.id);
        if (!tx.date.equals(date)) return reject("REVERSE", date, "REVERSAL_WINDOW", tx.id + " was made on " + tx.date);

        Account from = accountManager.getAccount(tx.fromId);
        Account to = accountManager.getAccount(tx.toId);
        to.balance = to.balance.subtract(tx.credited);
        BigDecimal back = tx.amount;
        if (from.tier.equals("PREMIUM")) {
            back = back.add(tx.fee);
            reportManager.addFee(date, from.currency, tx.fee.negate());
        }
        from.balance = from.balance.add(back);
        tx.reversed = true;
        String newId = nextTxId();
        txs.put(newId, new Transaction(newId, "REVERSE", date, tx.fromId, tx.toId, tx.amount, tx.currency, new BigDecimal("0.00"), tx.credited));
        return accept("REVERSE", date, newId, "reversed " + tx.id);
    }

    private String checkLimitAndFunds(String date, Account a, BigDecimal amount, BigDecimal fee) {
        BigDecimal limit = a.tier.equals("STANDARD") ? new BigDecimal("5000.00") : (a.tier.equals("PREMIUM") ? new BigDecimal("20000.00") : new BigDecimal("50000.00"));
        BigDecimal overdraft = a.tier.equals("PREMIUM") ? new BigDecimal("500.00") : BigDecimal.ZERO;
        if (accountManager.getUsedToday(a.id, date).add(amount).compareTo(limit) > 0) return "LIMIT_EXCEEDED: daily limit " + limit + " for " + a.tier;
        BigDecimal needed = amount.add(fee);
        if (a.balance.subtract(needed).compareTo(overdraft.negate()) < 0) return "INSUFFICIENT_FUNDS: balance " + a.balance + " " + a.currency + ", needed " + needed + " " + a.currency;
        return null;
    }

    private String nextTxId() { return String.format("TX-%06d", ++txSeq); }
    private String accept(String v, String d, String id, String e) {
        reportManager.count(d, 0); auditLogger.record(v, d, "OK " + id); return "OK " + id + " " + e;
    }
    private String reject(String v, String d, String c, String m) {
        reportManager.count(d, 1); auditLogger.record(v, d, "REJECTED " + c); return "REJECTED " + c + ": " + m;
    }
}

